Lemma fireo_0RB0LA_1LA1RC_0LD1RB_0RC1LD : forall (l0 l1 l2 l3 : list lstep) (t : Instr),
  srun_instr tm true true l0 O0_0RB0LA_1LA1RC_0LD1RB_0RC1LD0 = Some t ->
