    apply (lap_of_run tm Cc true true cho_0RB0LA_1LA1RC_0RD1RC_1LC1LB B0_0RB0LA_1LA1RC_0RD1RC_1LC1LB B1_0RB0LA_1LA1RC_0RD1RC_1LC1LB 4 14 p j' [] []).
