(** 0RB0LA_1LA1RC_0RD1RD_1LB1RC *)
(** 0RB0LA_1LA1RC_0RD1RD_1LB1RC -- the real machine (its counter grows RIGHT). *)
Definition tm_0RB0LA_1LA1RC_0RD1RD_1LB1RC : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB | StA, S1 => mk S0 DL StA
  | StB, S0 => mk S1 DL StA | StB, S1 => mk S1 DR StC
  | StC, S0 => mk S0 DR StD | StC, S1 => mk S1 DR StD
  | StD, S0 => mk S1 DL StB | StD, S1 => mk S1 DR StC end.

(** Its mirror 0LB0RA_1RA1LC_0LD1LD_1RB1LC: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB0LA_1LA1RC_0RD1RD_1LB1RC : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => mk S0 DR StA
  | StB, S0 => mk S1 DR StA | StB, S1 => mk S1 DL StC
  | StC, S0 => mk S0 DL StD | StC, S1 => mk S1 DL StD
  | StD, S0 => mk S1 DR StB | StD, S1 => mk S1 DL StC end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB0LA_1LA1RC_0RD1RD_1LB1RC : list Instr := [].
Definition tmw_0RB0LA_1LA1RC_0RD1RD_1LB1RC : TM := tm_wrap_trs tmm_0RB0LA_1LA1RC_0RD1RD_1LB1RC pins_0RB0LA_1LA1RC_0RD1RD_1LB1RC.
Local Notation tm := tmw_0RB0LA_1LA1RC_0RD1RD_1LB1RC.

Lemma mirror_ok_0RB0LA_1LA1RC_0RD1RD_1LB1RC : mirror_tm tm_0RB0LA_1LA1RC_0RD1RD_1LB1RC = tmm_0RB0LA_1LA1RC_0RD1RD_1LB1RC.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

