Lemma gz_0RB0LA_1LA1RC_1LD____1RB1RD : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_000_100_1 q0 ++ [S0]) [] 0 Z0_0RB0LA_1LA1RC_1LD____1RB1RD /\
