(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_0RB0LA_1LC0RD_1LA1LD_1RC1RD : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Bp q0 ++ [S0]) [] j A0_0RB0LA_1LC0RD_1LA1LD_1RC1RD.
