    apply (fireo_0RB0LA_1LC0RD_1LA1LD_1RC1RD [] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0LA_1LC0RD_1LA1LD_1RC1RD [SWinR 3] (StB, S1) ltac:(vm_compute; reflexivity)
