(** The chain into this family lands on its anchor up to 0/2
    trailing blanks. *)
Lemma gbo_0RB0LA_1LC0RD_1LA1RB_0LA1RC : forall j, lift (cden [] [] j BB1_0RB0LA_1LC0RD_1LA1RB_0LA1RC) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_0RB0LA_1LC0RD_1LA1RB_0LA1RC = (StB, (rep [S0;S1;S1] j ++ [S1], S0, (([]) ++ [S0]) ++ [S0]))).
  { unfold cden, BB1_0RB0LA_1LC0RD_1LA1RB_0LA1RC, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StB, (rep [S0;S1;S1] j ++ [S1], S0, []))).
  { unfold Cin_0RB0LA_1LC0RD_1LA1RB_0LA1RC. rewrite epow2_0RB0LA_1LC0RD_1LA1RB_0LA1RC.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_0RB0LA_1LC0RD_1LA1RB_0LA1RC. rewrite ?lift_app_blank. reflexivity.
