(** 0RB0LA_1LC0RD_1LA1RC_1RC1RD *)
(** 0RB0LA_1LC0RD_1LA1RC_1RC1RD -- the real machine (its counter grows RIGHT). *)
Definition tm_0RB0LA_1LC0RD_1LA1RC_1RC1RD : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB | StA, S1 => mk S0 DL StA
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S0 DR StD
  | StC, S0 => mk S1 DL StA | StC, S1 => mk S1 DR StC
  | StD, S0 => mk S1 DR StC | StD, S1 => mk S1 DR StD end.

(** Its mirror 0LB0RA_1RC0LD_1RA1LC_1LC1LD: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB0LA_1LC0RD_1LA1RC_1RC1RD : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => mk S0 DR StA
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S0 DL StD
  | StC, S0 => mk S1 DR StA | StC, S1 => mk S1 DL StC
  | StD, S0 => mk S1 DL StC | StD, S1 => mk S1 DL StD end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB0LA_1LC0RD_1LA1RC_1RC1RD : list Instr := [].
Definition tmw_0RB0LA_1LC0RD_1LA1RC_1RC1RD : TM := tm_wrap_trs tmm_0RB0LA_1LC0RD_1LA1RC_1RC1RD pins_0RB0LA_1LC0RD_1LA1RC_1RC1RD.
