Lemma mirror_ok_0RB0LA_1LC0RD_1LA1RC_1RC1RD : mirror_tm tm_0RB0LA_1LC0RD_1LA1RC_1RC1RD = tmm_0RB0LA_1LC0RD_1LA1RC_1RC1RD.
