Lemma geo_0RB0LA_1LC0RD_1LA1RC_1RC1RD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB0LA_1LC0RD_1LA1RC_1RC1RD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (KpCounter.cview_none_K p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB0LA_1LC0RD_1LA1RC_1RC1RD
             = (StD, (rep [S0] (S j) ++ [S1], S0, (([S1]) ++ [S0]) ++ [S0]))).
  { unfold cden, B1_0RB0LA_1LC0RD_1LA1RC_1RC1RD, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
