(** ** The lap *)

Lemma lap_0RB0LA_1LC0RD_1LA1RC_1RC1RD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0LA_1LC0RD_1LA1RC_1RC1RD p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB0LA_1LC0RD_1LA1RC_1RC1RD B0_0RB0LA_1LC0RD_1LA1RC_1RC1RD B1_0RB0LA_1LC0RD_1LA1RC_1RC1RD 2 12 p j' [] []).
    + exact run_ovf_0RB0LA_1LC0RD_1LA1RC_1RC1RD.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB0LA_1LC0RD_1LA1RC_1RC1RD p j' E).
    + exact (geo_0RB0LA_1LC0RD_1LA1RC_1RC1RD p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_0RB0LA_1LC0RD_1LA1RC_1RC1RD : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 16.
  assert (H : match csteps tm 16 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 16 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

