(** ** The lap *)

Lemma lap_0RB0LA_1LC0RD_1LA1RD_0RB1RC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
