    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB0LA_1LC0RD_1LA1RD_0RB1RC B0_0RB0LA_1LC0RD_1LA1RD_0RB1RC B1_0RB0LA_1LC0RD_1LA1RD_0RB1RC 4 24 p j' [] []).
    + exact run_ovf_0RB0LA_1LC0RD_1LA1RD_0RB1RC.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB0LA_1LC0RD_1LA1RD_0RB1RC p j' E).
    + exact (geo_0RB0LA_1LC0RD_1LA1RD_0RB1RC p j' E).
    + lia.
