  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (H1 & _).
  unfold Cin_0RB0LA_1LC1RB_0LD1LD_0RA0LC, cden, AI0_0RB0LA_1LC1RB_0LD1LD_0RA0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_0RB0LA_1LC1RB_0LD1LD_0RA0LC : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S1]) [] i AI1_0RB0LA_1LC1RB_0LD1LD_0RA0LC) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (_ & H2).
  unfold Cin_0RB0LA_1LC1RB_0LD1LD_0RA0LC, cden, AI1_0RB0LA_1LC1RB_0LD1LD_0RA0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S0;S0]) with ((([]) ++ [S0]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_0RB0LA_1LC1RB_0LD1LD_0RA0LC : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 12), (cden (Ip q0 ++ [S1]) [] i AI1_0RB0LA_1LC1RB_0LD1LD_0RA0LC).
  split; [lia|]. split; [| exact (gen_0RB0LA_1LC1RB_0LD1LD_0RA0LC v i q0 E)].
  rewrite (gsn_0RB0LA_1LC1RB_0LD1LD_0RA0LC v i q0 E).
  exact (srun_sound tm false true chn_0RB0LA_1LC1RB_0LD1LD_0RA0LC AI0_0RB0LA_1LC1RB_0LD1LD_0RA0LC AI1_0RB0LA_1LC1RB_0LD1LD_0RA0LC 4 12
           run_inner_0RB0LA_1LC1RB_0LD1LD_0RA0LC (Ip q0 ++ [S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/2
    trailing blanks. *)
Lemma gbo_0RB0LA_1LC1RB_0LD1LD_0RA0LC : forall j, lift (cden [] [] j BB1_0RB0LA_1LC1RB_0LD1LD_0RA0LC) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_0RB0LA_1LC1RB_0LD1LD_0RA0LC = (StB, (rep [S1;S0] j ++ [S1;S1], S0, (([]) ++ [S0]) ++ [S0]))).
  { unfold cden, BB1_0RB0LA_1LC1RB_0LD1LD_0RA0LC, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StB, (rep [S1;S0] j ++ [S1;S1], S0, []))).
  { unfold Cin_0RB0LA_1LC1RB_0LD1LD_0RA0LC. rewrite epow2_0RB0LA_1LC1RB_0LD1LD_0RA0LC.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_0RB0LA_1LC1RB_0LD1LD_0RA0LC. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_0RB0LA_1LC1RB_0LD1LD_0RA0LC : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_0RB0LA_1LC1RB_0LD1LD_0RA0LC.
Proof.
  intro j.
  destruct (ILCounter.cview_none_I (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_0RB0LA_1LC1RB_0LD1LD_0RA0LC, cden, BE0_0RB0LA_1LC1RB_0LD1LD_0RA0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_0RB0LA_1LC1RB_0LD1LD_0RA0LC : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. exact lapi_0RB0LA_1LC1RB_0LD1LD_0RA0LC. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB0LA_1LC1RB_0LD1LD_0RA0LC : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB0LA_1LC1RB_0LD1LD_0RA0LC p (pow2 j)).
  - exists (4 * j + 9), (cden [] [] j BB1_0RB0LA_1LC1RB_0LD1LD_0RA0LC).
    split; [lia|]. split; [| exact (gbo_0RB0LA_1LC1RB_0LD1LD_0RA0LC j)].
    rewrite (gso_0RB0LA_1LC1RB_0LD1LD_0RA0LC p j E).
    exact (srun_sound tm true true chb_0RB0LA_1LC1RB_0LD1LD_0RA0LC B0_0RB0LA_1LC1RB_0LD1LD_0RA0LC BB1_0RB0LA_1LC1RB_0LD1LD_0RA0LC 4 9
             run_boot_0RB0LA_1LC1RB_0LD1LD_0RA0LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 17), (cden [] [] j B1_0RB0LA_1LC1RB_0LD1LD_0RA0LC).
    split; [| exact (geo_0RB0LA_1LC1RB_0LD1LD_0RA0LC p j E)].
    rewrite (gxi_0RB0LA_1LC1RB_0LD1LD_0RA0LC j).
    exact (srun_sound tm true true che_0RB0LA_1LC1RB_0LD1LD_0RA0LC BE0_0RB0LA_1LC1RB_0LD1LD_0RA0LC B1_0RB0LA_1LC1RB_0LD1LD_0RA0LC 4 17
             run_exit_0RB0LA_1LC1RB_0LD1LD_0RA0LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_0RB0LA_1LC1RB_0LD1LD_0RA0LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0LA_1LC1RB_0LD1LD_0RA0LC p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB0LA_1LC1RB_0LD1LD_0RA0LC p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_0RB0LA_1LC1RB_0LD1LD_0RA0LC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 14.
  assert (H : match csteps tm 14 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 14 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB0LA_1LC1RB_0LD1LD_0RA0LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB0LA_1LC1RB_0LD1LD_0RA0LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB0LA_1LC1RB_0LD1LD_0RA0LC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB0LA_1LC1RB_0LD1LD_0RA0LC p j E)].
Qed.


(** An instruction that fires ONLY inside the interior lap: [vis_via_ovf] runs to an
    OVERFLOW anchor, so it cannot see one.  This is the interior witness, and
    [LapCertGlueLift.fire_via_int_lift] carries it to every anchor. *)
Lemma firei_0RB0LA_1LC1RB_0LD1LD_0RA0LC : forall (l : list lstep) (t : Instr),
  srun_instr tm false true l A0_0RB0LA_1LC1RB_0LD1LD_0RA0LC = Some t ->
  forall p j q0, cview p = (j, Some q0) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j q0 E.
