Lemma geo_0RB0LA_1RC0LA_0RD1RD_1LB1RD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB0LA_1RC0LA_0RD1RD_1LB1RD) = lift (Cc (Pos.succ p)).
