  intros p j E. destruct (KpCounter.cview_none_K p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB0LA_1RC0LA_0RD1RD_1LB1RD
             = (StD, (rep [S0] (S j) ++ [S1], S0, ([S0;S1]) ++ [S0]))).
