(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_0RB0LA_1RC0LC_1LA0RD_1LC0RD : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] 0 Z0_0RB0LA_1RC0LC_1LA0RD_1LC0RD /\
  lift (cden (Kp q0 ++ [S0]) [] 0 Z1_0RB0LA_1RC0LC_1LA0RD_1LC0RD) = lift (Cc (Pos.succ p)).
Proof.
  intros p q0 E. destruct (KpCounter.cview_some_K p 0 q0 E) as (H1 & H2).
  unfold Cc_0RB0LA_1RC0LC_1LA0RD_1LC0RD, cden, Z0_0RB0LA_1RC0LC_1LA0RD_1LC0RD, Z1_0RB0LA_1RC0LC_1LA0RD_1LC0RD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - cbn [rep app Nat.mul Nat.add]; rewrite ?app_nil_r.
    change ([S1;S0]) with (([S1]) ++ [S0]).
    rewrite !lift_app_blank.
    rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_0RB0LA_1RC0LC_1LA0RD_1LC0RD : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] j P0_0RB0LA_1RC0LC_1LA0RD_1LC0RD /\
  lift (cden (Kp q0 ++ [S0]) [] j P1_0RB0LA_1RC0LC_1LA0RD_1LC0RD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (KpCounter.cview_some_K p (S j) q0 E) as (H1 & H2).
  unfold Cc_0RB0LA_1RC0LC_1LA0RD_1LC0RD, cden, P0_0RB0LA_1RC0LC_1LA0RD_1LC0RD, P1_0RB0LA_1RC0LC_1LA0RD_1LC0RD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - cbn [rep app Nat.mul Nat.add]; rewrite ?app_nil_r.
    change ([S1;S0]) with (([S1]) ++ [S0]).
    rewrite !lift_app_blank.
    rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB0LA_1RC0LC_1LA0RD_1LC0RD : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
