    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB0LA_1RC0RD_1LA1LC_1RB0LC (StB, S0)).
    intros p1 j1 E1.
    exact (firex_0RB0LA_1RC0RD_1LA1LC_1RB0LC [SRotL 1; SWin 1; SCycL 2 0; SWinL 2] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_0RB0LA_1RC0RD_1LA1LC_1RB0LC
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_0RB0LA_1RC0RD_1LA1LC_1RB0LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 2]).
    vm_compute; reflexivity.
  - (* C1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB0LA_1RC0RD_1LA1LC_1RB0LC (StC, S1)).
    intros p1 j1 E1.
    exact (firex_0RB0LA_1RC0RD_1LA1LC_1RB0LC [SRotL 1; SWin 1; SCycL 2 0; SWinL 12] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB0LA_1RC0RD_1LA1LC_1RB0LC (StD, S0)).
    intros p1 j1 E1.
    exact (firex_0RB0LA_1RC0RD_1LA1LC_1RB0LC [SRotL 1; SWin 1; SCycL 2 0; SWinL 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_0RB0LA_1RC0RD_1LA1LC_1RB0LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
Qed.

