    apply (lap_of_run tm Cc true true cho_0RB0LA_1RC1LA_1RD1RB_0LD1LC B0_0RB0LA_1RC1LA_1RD1RB_0LD1LC B1_0RB0LA_1RC1LA_1RD1RB_0LD1LC 4 12 p j' [] []).
